     values ('74ec4e72-afc0-4e76-9918-53a63f11daa8', '9f40d966-8a90-45fc-b7d3-4861f5918e43', 'd91a02cc-8255-465a-bc52-be04a883f810', 'Even wall thickness all the way down. Envious.', null, now() - interval '107525 seconds');
     values ('e57e3516-921a-4083-9134-50206c79dea7', '9f40d966-8a90-45fc-b7d3-4861f5918e43', 'e36648ad-ae34-420b-8177-6eff2bb3ad5b', 'How long did you let it dry after rough turning? I always get impatient and it ovals on me.', null, now() - interval '87880 seconds');
     values ('b156606c-de35-455c-b00e-04099f7a5eca', '9f40d966-8a90-45fc-b7d3-4861f5918e43', '391da3b7-e0f9-42b8-9e58-30c08eae11df', 'Paper bag, shavings inside, about eight months. I weigh it every couple of weeks and wait until it stops losing weight.', 'e57e3516-921a-4083-9134-50206c79dea7', now() - interval '64922 seconds');
     values ('559de15b-9ea8-4ce5-95f3-e88fcf70dd0f', '9f40d966-8a90-45fc-b7d3-4861f5918e43', '3916339e-7bd6-43db-a5eb-5f518f9fc522', 'Weighing it is such a good idea. Stealing that.', null, now() - interval '39508 seconds');
     select '0d906ca5-4295-45a3-938b-d514d36a1c1b', id, '0f34f5c2-dc1a-4171-8687-3ee6cc4bd5fc', 'End grain cutting boards for the holidays (batch of six)', 'Every year I tell myself I won''t do this and every year I do. Six end grain boards, maple and walnut checkerboard. Lessons this year: Use a drum sander if you can borrow one. Belt sanding end grain is misery. Chamfer the', false, false, now() - interval '777600 seconds', now() - interval '777600 seconds'
       from categories where slug = 'projects';
     values ('ede51cf7-8bdc-42fd-b3a6-215f222c5da6', '0d906ca5-4295-45a3-938b-d514d36a1c1b', '0f34f5c2-dc1a-4171-8687-3ee6cc4bd5fc', 'Every year I tell myself I won''t do this and every year I do. Six end grain boards, maple and walnut checkerboard.

![end grain board, maple and walnut](/media/5d271be4-f8af-4630-81af-749fff13d768/5c625d10f921be3e93efdf2108fbbfb72e8fc33db0fdfabd870d7609ea75e526)

Lessons this year:

1. Use a drum sander if you can borrow one. Belt sanding end grain is misery.
2. Chamfer the bottom edge before the second glue-up or you *will* tear out the corners.
3. Mineral oil until it stops soaking in, then a board butter with beeswax.', true, now() - interval '777600 seconds');
     values ('0293f28c-f5eb-4741-9330-a0f0abd440a8', '0d906ca5-4295-45a3-938b-d514d36a1c1b', 'fc593465-0ef8-423f-be4c-c368c0817818', 'Tear-out on the exit side of the router sled got me last time. Did you use a backer block?', null, now() - interval '721834 seconds');
     values ('dda45995-0889-422c-8b97-04e4e08601a0', '0d906ca5-4295-45a3-938b-d514d36a1c1b', '0f34f5c2-dc1a-4171-8687-3ee6cc4bd5fc', 'Sacrificial strip glued to the end, trimmed off after. Clean every time.', '0293f28c-f5eb-4741-9330-a0f0abd440a8', now() - interval '640287 seconds');
     values ('8a49bd5e-ccc6-4ccf-903c-3086484b7cb2', '0d906ca5-4295-45a3-938b-d514d36a1c1b', '62531dae-f44b-4748-a0d9-0bada8b21385', 'These are gorgeous. The alignment on the checkerboard is dead on.', null, now() - interval '544990 seconds');
     values ('72feaa01-5014-4fc1-9bd3-bc2dad50f86c', '0d906ca5-4295-45a3-938b-d514d36a1c1b', '2665ed2d-dce2-4852-b1f1-e64c9c92ae08', 'Point 2 is so true. I''ve lost corners on three boards before I learned that.', null, now() - interval '439497 seconds');
     values ('613cf443-c8ce-4d5a-876c-122bd4797f79', '0d906ca5-4295-45a3-938b-d514d36a1c1b', 'e36648ad-ae34-420b-8177-6eff2bb3ad5b', 'One thing I taught students: glue up end grain with a slightly thicker glue line than long grain. Those pores drink it.', null, now() - interval '325710 seconds');
     values ('50d43515-4972-4191-9e11-57926706cb08', '0d906ca5-4295-45a3-938b-d514d36a1c1b', '0f34f5c2-dc1a-4171-8687-3ee6cc4bd5fc', 'Good tip. I''ve been doing a thin first coat, wait five minutes, then a second before clamping.', '613cf443-c8ce-4d5a-876c-122bd4797f79', now() - interval '204846 seconds');
