       from categories where slug = 'projects';
     values ('6a4a243d-121d-4729-a8c1-e7f1d47b3a3b', '5304902f-b6ea-43e0-a2ae-97c2e1324f46', 'd91a02cc-8255-465a-bc52-be04a883f810', 'Twelfth windsor, first one I''m fully happy with. Hickory spindles, white oak bow, pine seat. Milk paint in black over red.

