     values ('73032494-3344-40b7-993a-259f41d028e4', '5304902f-b6ea-43e0-a2ae-97c2e1324f46', '0f42ea3b-28d9-46ec-8aaa-7d8f615308b3', 'Twelve chairs to get one you''re happy with sounds about right. Congratulations.', null, now() - interval '1228862 seconds');
