     select '9abd1d17-f132-4b9d-a43b-632ff773cdae', id, '0f34f5c2-dc1a-4171-8687-3ee6cc4bd5fc', 'Glue-up keeps coming out of square', 'Cabinet carcass, pocket screws plus glue. Every time I clamp it, it racks by 1/8 inch diagonally. Checking diagonals before the glue sets but I can''t pull it back.', false, false, now() - interval '518400 seconds', now() - interval '518400 seconds'
       from categories where slug = 'help';
     values ('ad5120ef-7bcf-479c-84a1-a7e7b7006768', '9abd1d17-f132-4b9d-a43b-632ff773cdae', '0f34f5c2-dc1a-4171-8687-3ee6cc4bd5fc', 'Cabinet carcass, pocket screws plus glue. Every time I clamp it, it racks by 1/8 inch diagonally.

Checking diagonals before the glue sets but I can''t pull it back.', true, now() - interval '518400 seconds');
     values ('cc2326c8-f651-4a3e-ba23-3ae34eb5c480', '9abd1d17-f132-4b9d-a43b-632ff773cdae', '0f42ea3b-28d9-46ec-8aaa-7d8f615308b3', 'Where are your clamps? If they''re not directly in line with the joints, they''ll pull the box out of square.', null, now() - interval '460823 seconds');
     values ('1ff1dec7-2f08-4de3-9027-2649a75be093', '9abd1d17-f132-4b9d-a43b-632ff773cdae', 'fc593465-0ef8-423f-be4c-c368c0817818', 'Put a back panel in during the glue-up. It squares the case for you.', null, now() - interval '376630 seconds');
     values ('bdd4d609-2e83-40e0-9539-915fbed1a62a', '9abd1d17-f132-4b9d-a43b-632ff773cdae', 'e36648ad-ae34-420b-8177-6eff2bb3ad5b', 'Clamp pressure centered on the joint line, and use a diagonal clamp across the long diagonal to pull it back. Measure, nudge, measure.', null, now() - interval '278238 seconds');
     values ('56fd0432-1ed4-49b5-b50b-3ee89483a420', '9abd1d17-f132-4b9d-a43b-632ff773cdae', '0f34f5c2-dc1a-4171-8687-3ee6cc4bd5fc', 'Moved the clamps onto the joint lines and it came out within 1/32. Unbelievable.', 'bdd4d609-2e83-40e0-9539-915fbed1a62a', now() - interval '169320 seconds');
