     values ('290b412d-b29b-493e-bcae-3001160649d6', '2c6d2a90-28ad-4f28-ad93-8d2ba4604da6', 'd91a02cc-8255-465a-bc52-be04a883f810', 'Pine seat blanks for windsors are checking on the ends as they dry. Sealing with wax but still getting cracks.', true, now() - interval '1728000 seconds');
